package com.puck.finance;
import org.springframework.web.bind.annotation.*;
import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.*;
import java.math.BigDecimal;
import java.time.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.io.*;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.pdmodel.font.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

@RestController @RequestMapping("/api") public class Api {
 final Users users; final Sessions sessions; final Entries entries; final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); final SecureRandom random=new SecureRandom();
 Api(Users u,Sessions s,Entries e){users=u;sessions=s;entries=e;}
 record Credentials(String name,String email,String password){} record Input(String type,String description,String category,@JsonDeserialize(using=DecimalString.class) String amount,String date){}
 record View(Long id,String type,String description,String category,String amount,String date,Instant createdAt,Instant updatedAt){}
 record Summary(String income,String expense,String balance,long count){}
 static ResponseStatusException err(HttpStatus s){return new ResponseStatusException(s);}
 static String clean(String s,int max){if(s==null || s.trim().isEmpty() || s.trim().length()>max) throw err(HttpStatus.BAD_REQUEST); return s.trim();}
 static String email(String s){s=clean(s,254).toLowerCase(Locale.ROOT); if(!Pattern.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$",s))throw err(HttpStatus.BAD_REQUEST); return s;}
 static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 Session session(String auth){if(auth==null || !auth.startsWith("Bearer "))throw err(HttpStatus.UNAUTHORIZED); Session s=sessions.findByTokenHash(hash(auth.substring(7))).orElseThrow(()->err(HttpStatus.UNAUTHORIZED)); if(!s.expiresAt.isAfter(Instant.now()))throw err(HttpStatus.UNAUTHORIZED);return s;}
 @PostMapping("/auth/register") @ResponseStatus(HttpStatus.CREATED) Object register(@RequestBody Credentials c){String name=clean(c.name,120), email=email(c.email); if(c.password==null || c.password.length()<12 || c.password.length()>128)throw err(HttpStatus.BAD_REQUEST); if(users.findByEmail(email).isPresent())throw err(HttpStatus.CONFLICT); User u=new User();u.name=name;u.email=email;u.passwordHash=encoder.encode(hash(c.password));try{users.saveAndFlush(u);}catch(DataIntegrityViolationException ex){throw err(HttpStatus.CONFLICT);}return Map.of("id",u.id,"name",u.name,"email",u.email);}
 @PostMapping("/auth/login") Object login(@RequestBody Credentials c){String em=email(c.email);User u=users.findByEmail(em).orElse(null);if(u==null || c.password==null || !encoder.matches(hash(c.password),u.passwordHash))throw err(HttpStatus.UNAUTHORIZED);byte[] bytes=new byte[32];random.nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);Session s=new Session();s.tokenHash=hash(token);s.userId=u.id;s.expiresAt=Instant.now().plus(Duration.ofHours(12));sessions.save(s);return Map.of("token",token);}
 @PostMapping("/auth/logout") @ResponseStatus(HttpStatus.NO_CONTENT) void logout(@RequestHeader(value="Authorization",required=false) String a){sessions.delete(session(a));}
 @GetMapping("/auth/me") Object me(@RequestHeader(value="Authorization",required=false) String a){User u=users.findById(session(a).userId).orElseThrow(()->err(HttpStatus.UNAUTHORIZED));return Map.of("id",u.id,"name",u.name,"email",u.email);}
 static BigDecimal amount(String s){if(s==null || !s.matches("(?:0|[1-9][0-9]{0,13})(?:\\.[0-9]{1,2})?"))throw err(HttpStatus.BAD_REQUEST);BigDecimal n=new BigDecimal(s);if(n.signum()<=0)throw err(HttpStatus.BAD_REQUEST);return n.setScale(2);}
 static BigDecimal bound(String s){if(s==null || !s.matches("(?:0|[1-9][0-9]{0,13})(?:\\.[0-9]{1,2})?"))throw err(HttpStatus.BAD_REQUEST);return new BigDecimal(s).setScale(2);}
 static LocalDate date(String s){try{return LocalDate.parse(s);}catch(Exception e){throw err(HttpStatus.BAD_REQUEST);}}
 static void fill(Entry e,Input i){if(i==null || !("INCOME".equals(i.type)||"EXPENSE".equals(i.type)))throw err(HttpStatus.BAD_REQUEST);e.type=i.type;e.description=clean(i.description,255);e.category=clean(i.category,80);e.amount=amount(i.amount);e.date=date(i.date);e.updatedAt=Instant.now();}
 static View view(Entry e){return new View(e.id,e.type,e.description,e.category,e.amount.setScale(2).toPlainString(),e.date.toString(),e.createdAt,e.updatedAt);}
 Entry owned(Long id,Long uid){return entries.findByIdAndUserId(id,uid).orElseThrow(()->err(HttpStatus.NOT_FOUND));}
 @PostMapping("/transactions") @ResponseStatus(HttpStatus.CREATED) View create(@RequestHeader(value="Authorization",required=false) String a,@RequestBody Input i){Entry e=new Entry();e.userId=session(a).userId;fill(e,i);e.createdAt=e.updatedAt;return view(entries.save(e));}
 @GetMapping("/transactions/{id:[0-9]+}") View get(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){return view(owned(id,session(a).userId));}
 @PutMapping("/transactions/{id:[0-9]+}") View update(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id,@RequestBody Input i){Entry e=owned(id,session(a).userId);fill(e,i);return view(entries.save(e));}
 @DeleteMapping("/transactions/{id:[0-9]+}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){entries.delete(owned(id,session(a).userId));}
 List<Entry> select(String auth,Map<String,String> p){Long uid=session(auth).userId;String type=p.get("type"),cat=p.get("category"),desc=p.get("description");if(type!=null&&!type.equals("INCOME")&&!type.equals("EXPENSE"))throw err(HttpStatus.BAD_REQUEST);LocalDate start=p.containsKey("startDate")?date(p.get("startDate")):null,end=p.containsKey("endDate")?date(p.get("endDate")):null;BigDecimal min=p.containsKey("minAmount")?bound(p.get("minAmount")):null,max=p.containsKey("maxAmount")?bound(p.get("maxAmount")):null;if(start!=null&&end!=null&&start.isAfter(end)||min!=null&&max!=null&&min.compareTo(max)>0)throw err(HttpStatus.BAD_REQUEST);String sort=p.getOrDefault("sort","date,desc");Comparator<Entry> comp=switch(sort){case "date,asc" -> Comparator.comparing(e->e.date);case "date,desc" -> Comparator.comparing((Entry e)->e.date).reversed();case "amount,asc" -> Comparator.comparing(e->e.amount);case "amount,desc" -> Comparator.comparing((Entry e)->e.amount).reversed();default -> throw err(HttpStatus.BAD_REQUEST);};return entries.findByUserId(uid).stream().filter(e->type==null||e.type.equals(type)).filter(e->cat==null||e.category.equals(cat)).filter(e->desc==null||e.description.toLowerCase(Locale.ROOT).contains(desc.toLowerCase(Locale.ROOT))).filter(e->start==null||!e.date.isBefore(start)).filter(e->end==null||!e.date.isAfter(end)).filter(e->min==null||e.amount.compareTo(min)>=0).filter(e->max==null||e.amount.compareTo(max)<=0).sorted(comp.thenComparing(e->e.id)).toList();}
 static int number(String s,int def,int min,int max){try{int n=s==null?def:Integer.parseInt(s);if(n<min||n>max)throw new Exception();return n;}catch(Exception e){throw err(HttpStatus.BAD_REQUEST);}}
 @GetMapping("/transactions") Object list(@RequestHeader(value="Authorization",required=false) String a,@RequestParam Map<String,String> p){int page=number(p.get("page"),0,0,Integer.MAX_VALUE),size=number(p.get("size"),20,1,100);List<Entry> all=select(a,p);int from=(int)Math.min((long)page*size,all.size()),to=Math.min(from+size,all.size());return Map.of("content",all.subList(from,to).stream().map(Api::view).toList(),"totalElements",all.size(),"page",page,"size",size,"totalPages",(all.size()+size-1)/size);}
 static Summary summary(List<Entry> all){BigDecimal in=BigDecimal.ZERO,out=BigDecimal.ZERO;for(Entry e:all)if(e.type.equals("INCOME"))in=in.add(e.amount);else out=out.add(e.amount);return new Summary(in.setScale(2).toPlainString(),out.setScale(2).toPlainString(),in.subtract(out).setScale(2).toPlainString(),all.size());}
 @GetMapping("/transactions/summary") Summary sum(@RequestHeader(value="Authorization",required=false) String a,@RequestParam Map<String,String> p){return summary(select(a,p));}
 @GetMapping("/transactions/export.xlsx") ResponseEntity<byte[]> xlsx(@RequestHeader(value="Authorization",required=false) String a,@RequestParam Map<String,String> p)throws IOException{List<Entry> all=select(a,p);try(XSSFWorkbook w=new XSSFWorkbook();ByteArrayOutputStream b=new ByteArrayOutputStream()){var sh=w.createSheet("Movimentações");int row=0;var h=sh.createRow(row++);String[] headers={"Data","Tipo","Descrição","Categoria","Valor"};for(int i=0;i<headers.length;i++)h.createCell(i).setCellValue(headers[i]);for(Entry e:all){var r=sh.createRow(row++);String[] vals={e.date.toString(),e.type,e.description,e.category,e.amount.toPlainString()};for(int i=0;i<vals.length;i++)r.createCell(i).setCellValue(vals[i]);}Summary s=summary(all);var r=sh.createRow(row);r.createCell(0).setCellValue("Entradas: "+s.income+" Saídas: "+s.expense+" Saldo: "+s.balance);for(int i=0;i<5;i++)sh.autoSizeColumn(i);w.write(b);return file(b.toByteArray(),"movimentacoes.xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");}}
 @GetMapping("/transactions/export.pdf") ResponseEntity<byte[]> pdf(@RequestHeader(value="Authorization",required=false) String a,@RequestParam Map<String,String> p)throws IOException{List<Entry> all=select(a,p);try(PDDocument d=new PDDocument();ByteArrayOutputStream b=new ByteArrayOutputStream()){List<String> lines=new ArrayList<>();lines.add("Movimentacoes financeiras");for(Entry e:all)lines.add(e.date+" | "+e.type+" | "+e.description+" | "+e.category+" | "+e.amount.toPlainString());Summary s=summary(all);lines.add("Entradas: "+s.income+" Saidas: "+s.expense+" Saldo: "+s.balance);PDType0Font font=PDType0Font.load(d,Api.class.getResourceAsStream("/DejaVuSans.ttf")); List<String> wrapped=new ArrayList<>(); for(String line:lines){while(line.length()>70){wrapped.add(line.substring(0,70));line=line.substring(70);}wrapped.add(line);} PDPageContentStream c=null;int y=0;for(String line:wrapped){if(c==null||y<40){if(c!=null)c.close();PDPage page=new PDPage();d.addPage(page);c=new PDPageContentStream(d,page);y=750;}c.beginText();c.setFont(font,9);c.newLineAtOffset(35,y);String safe=line.replaceAll("[\\p{Cntrl}]", " "); StringBuilder printable=new StringBuilder(); safe.codePoints().forEach(cp->{try { font.encode(new String(Character.toChars(cp))); printable.appendCodePoint(cp); } catch (Exception ex) { printable.append('?'); }}); String text=printable.toString(); while(font.getStringWidth(text)>58000 && text.length()>1) text=text.substring(0,text.length()-1); c.showText(text);c.endText();y-=15;}if(c!=null)c.close();d.save(b);return file(b.toByteArray(),"movimentacoes.pdf","application/pdf");}}
 static ResponseEntity<byte[]> file(byte[] data,String name,String type){return ResponseEntity.ok().header("Content-Disposition","attachment; filename=\""+name+"\"").contentType(MediaType.parseMediaType(type)).body(data);}
}
